#!/usr/bin/env ruby
require'rexml/document';require'json';require'fileutils';root=File.expand_path('..',__dir__);pom=REXML::Document.new(File.read(File.join(root,'pom.xml')));modules=REXML::XPath.match(pom,'/project/modules/module').map{|n|n.text.strip};files=modules.flat_map{|m|Dir.glob(File.join(root,m,'target/*.jar'))}.reject{|p|p.end_with?('-sources.jar','-javadoc.jar')}+Dir.glob(File.join(root,'database/migrations/*.sql'))+[File.join(root,'deploy/production-services.yaml'),File.join(root,'protocol/aoo-protocol-v2.json'),File.join(root,'work/release/SHA512SUMS')];files.select!{|p|File.file?(p)};abort 'no reactor jars available' if files.none?{|p|p.end_with?('.jar')};manifest=files.sort.map{|p|p.delete_prefix(root+'/')};out=File.join(root,'work/release/release-content.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate({schemaVersion:1,files:manifest})+"\n");exec('tar','-czf',File.join(root,'work/release/aoo-release.tar.gz'),'-C',root,*manifest)
